"""Generate public documentation from the package's single catalogue source."""

from __future__ import annotations

import argparse
import hashlib
import json
from collections import Counter
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def render() -> str:
    doc = json.loads((ROOT / "rdk_lab/data/catalogue.json").read_text(encoding="utf-8"))
    counts = Counter(row["group"] for row in doc["entries"])
    lines = [
        "# Algorithm catalogue",
        "",
        "<!-- Generated by tools/render_catalogue.py. Edit the JSON source, not this table. -->",
        "",
        f"Snapshot: **{doc['as_of']}**.",
        "",
        "These are registry entries, not unique models, deployment counts or shipped recipes.",
        "Targets are intended scope; the status and note state what was actually observed.",
        "Every row is a maintainer-reported historical observation, not a public raw-evidence certification.",
        "",
        f"Official: {counts['official']} entries · Frontier: {counts['frontier']} · Research: {counts['research']}.",
        "",
        "No full upstream model or vendor binary is bundled. See [results](results.md),",
        "[recipe availability](../recipes/README.md) and [asset notes](../registry/asset_review.json).",
        "",
    ]
    for group in ("official", "frontier", "research"):
        lines.extend([f"## {group.title()}", ""])
        for row in doc["entries"]:
            if row["group"] != group:
                continue
            lines.extend(
                [
                    f"### {row['id']} · {row['name']}",
                    "",
                    f"Intended targets: {', '.join(row['intended_targets'])}.",
                    "",
                    f"Status: `{row['observed_status']}`.",
                    "",
                    row["scope_note"],
                    "",
                ]
            )
    lines.extend(["## Counting and provenance", "", "Known overlaps:", ""])
    for overlap in doc["overlaps"]:
        lines.append(f"- {', '.join(overlap['ids'])}: {overlap['reason']}")
    lines.extend(
        [
            "",
            "[Machine-readable source](../rdk_lab/data/catalogue.json) · [Source commitments](../registry/snapshot_provenance.json)",
            "",
        ]
    )
    return "\n".join(lines)


def fixture_manifest() -> str:
    path = ROOT / "examples/fixture/values.json"
    doc = {
        "schema_version": 1,
        "fixture_id": "scalar-relu-reference-v1",
        "files": [
            {
                "path": path.name,
                "size_bytes": path.stat().st_size,
                "sha256": hashlib.sha256(path.read_bytes()).hexdigest(),
            }
        ],
    }
    return json.dumps(doc, sort_keys=True, indent=2) + "\n"


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    generated = {
        ROOT / "docs/catalogue.md": render(),
        ROOT / "examples/fixture/manifest.json": fixture_manifest(),
    }
    stale = []
    for path, text in generated.items():
        if args.check:
            if not path.is_file() or path.read_text(encoding="utf-8") != text:
                stale.append(path.relative_to(ROOT).as_posix())
        else:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(text, encoding="utf-8", newline="\n")
    if stale:
        print("Generated files out of date: " + ", ".join(stale))
        return 1
    print("Generated catalogue and fixture manifest: " + ("PASS" if args.check else "written"))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
